export type ProgramFieldName = keyof typeof PROGRAM_FIELD_IDS

/**
 * The Program collection's link to a Mentor. The export flattens the linked item
 * alongside it as `<linkFieldId>_<mentorFieldId>`, which is how the mentor block
 * on a programme page gets its values -- so repointing the link means rewriting
 * that whole prefixed set, not just this one key.
 */
export const PROGRAM_MENTOR_FIELD_ID = 'bw5wYLxeb'

export type ProgramOverride = {
    /** Plain values, replacing the snapshot's outright. */
    fields?: Partial<Record<ProgramFieldName, unknown>>
    /**
     * Patches for fields whose value is a component embed, keyed by field name
     * and indexed by position in the embed list. Each patch is merged over that
     * embed's existing `props`, so icons and `--token-` colours stay whatever
     * the snapshot says and keep tracking Framer. Only text needs restating.
     *
     * Merging also preserves the empty-string props the cards rely on:
     * `listItem05: ''` means "hide this row", and dropping the key entirely
     * would show a placeholder instead.
     */
    embeds?: Partial<Record<ProgramFieldName, Array<Record<string, unknown>>>>
    /** Existing CMS mentor slug, or a local profile for someone in our team grid. */
    mentor?: string | {
        slug: string
        name: string
        image: string
        role: string
        description: string
        expertise: string[]
    }
}

